package local.snapexplorer.mobile;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.os.*;import android.view.*;import android.widget.*;import android.text.*;import android.text.style.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Compact mode must keep one visible bubble even when a folded copy is highlighted. */
public final class CompactSearchSmoke extends Instrumentation {
 private int checks;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();try{run();out.putString("stream","PASS "+checks+" compact-search Android checks\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream",s.toString());finish(Activity.RESULT_CANCELED,out);}}
 private void check(boolean ok,String s){if(!ok)throw new AssertionError(s);checks++;}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void invoke(Activity a,String method){runOnMainSync(()->{try{Method m=a.getClass().getDeclaredMethod(method);m.setAccessible(true);m.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});}
 private void compact(Activity a,boolean enabled){runOnMainSync(()->{try{Method m=a.getClass().getDeclaredMethod("setCompactMode",boolean.class);m.setAccessible(true);m.invoke(a,enabled);}catch(Exception e){throw new RuntimeException(e);}});}
 private void older(Activity a){runOnMainSync(()->{try{Method m=a.getClass().getDeclaredMethod("load",int.class,long.class);m.setAccessible(true);m.invoke(a,-1,0L);}catch(Exception e){throw new RuntimeException(e);}});}
 private void idle(Activity a)throws Exception{for(int i=0;i<300;i++){waitForIdleSync();if(!(Boolean)field(a,"busy")&&!(Boolean)field(a,"finding")&&!(Boolean)field(a,"resultsLoading")){SystemClock.sleep(150);return;}SystemClock.sleep(100);}throw new AssertionError("Reader busy");}
 private int visible(Activity a,String body)throws Exception{int n=0;for(Object e:(List<?>)field(a,"entries"))if(((ChatRepository.Row)field(e,"row")).text.equals(body))n++;return n;}
 private void search(Activity a,String query)throws Exception{invoke(a,"search");runOnMainSync(()->{try{EditText input=(EditText)field(a,"searchInput");input.setText(query);input.onEditorAction(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);}catch(Exception e){throw new RuntimeException(e);}});idle(a);}
 private void select(Activity a,String sender)throws Exception{List<?> hits=(List<?>)field(a,"searchResults");int pos=-1;for(int i=0;i<hits.size();i++)if(((ChatRepository.Row)hits.get(i)).sender.equals(sender)){pos=i;break;}final int p=pos;ListView list=(ListView)field(a,"resultsList");runOnMainSync(()->list.performItemClick(list.getAdapter().getView(p,null,list),p,list.getAdapter().getItemId(p)));idle(a);}
 private boolean hasRepeatControl(View v){if(v instanceof Button)return true;if(v instanceof TextView){String t=((TextView)v).getText().toString();if(t.contains("grouped entries")||t.contains("matching entries")||t.contains("expand"))return true;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(hasRepeatControl(((ViewGroup)v).getChildAt(i)))return true;return false;}
 private boolean highlighted(View v){if(v instanceof TextView){CharSequence s=((TextView)v).getText();if(s instanceof Spanned&&((Spanned)s).getSpans(0,s.length(),BackgroundColorSpan.class).length>0)return true;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(highlighted(((ViewGroup)v).getChildAt(i)))return true;return false;}
 private void add(SQLiteDatabase db,String chat,String sender,String body,int own,String external){db.execSQL("INSERT INTO messages(chat,sender,body,kind,date,epoch,own,external_id) VALUES (?,?,?,'TEXT','date',1800000001000,?,?)",new Object[]{chat,sender,body,own,external});}
 private void run()throws Exception{
  getUiAutomation();Context c=getTargetContext();File zip=new File(c.getCacheDir(),"compact-search-synthetic.zip");try(InputStream in=c.getAssets().open("sample.zip");OutputStream out=new FileOutputStream(zip)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
  ChatRepository repo=new ChatRepository(c);repo.importArchives(Collections.singletonList(new ChatRepository.Input(zip,"Synthetic compact-search source",false)),true,(a,b)->{});SQLiteDatabase db=repo.getWritableDatabase();db.execSQL("INSERT INTO chats(id,title) VALUES ('compact','Compact test')");db.execSQL("INSERT INTO chats(id,title) VALUES ('boundary','Boundary test')");
  add(db,"compact","OwnerExample","Repeated example",1,"copy-one");add(db,"compact","OwnerExample","Repeated example",0,"copy-two");add(db,"compact","OtherExample","Repeated example",0,"real-other-sender");
  add(db,"boundary","OwnerExample","Boundary marker",1,"boundary-one");for(int i=0;i<99;i++)add(db,"boundary","OwnerExample","Filler "+i,1,"filler-"+i);add(db,"boundary","OwnerExample","Boundary marker",0,"boundary-two");db.execSQL("INSERT OR REPLACE INTO message_search(docid,body,sender) SELECT id,body,sender FROM messages");
  c.getSharedPreferences("display",0).edit().putString("my_sender","OwnerExample").commit();c.getSharedPreferences("chat_reader",0).edit().putBoolean("compact:compact",true).putBoolean("compact:boundary",true).commit();
  Activity chat=startActivitySync(new Intent(c,ChatActivity.class).putExtra("chat","compact").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));idle(chat);check(visible(chat,"Repeated example")==2,"Initial compact view folds same-sender pair and retains actual other sender");search(chat,"Repeated");select(chat,"OwnerExample");
  check(visible(chat,"Repeated example")==1,"Selecting a duplicate search hit must not pull it out as a second visible bubble");
  Object entry=((List<?>)field(chat,"entries")).get(0);check(((List<?>)field(entry,"copies")).size()==1,"Highlighted group keeps its original copy available");long hit=((ChatRepository.Row)field(chat,"searchHit")).id;check(((ChatRepository.Row)field(entry,"row")).id!=hit,"Regression targets the folded copy rather than only the canonical row");
  final boolean[] marked={false};runOnMainSync(()->{try{Method m=chat.getClass().getDeclaredMethod("bubble",entry.getClass(),int.class);m.setAccessible(true);marked[0]=highlighted((View)m.invoke(chat,entry,0));}catch(Exception e){throw new RuntimeException(e);}});check(marked[0],"Remaining group bubble is highlighted for a hit on its folded copy");
  final boolean[] ordinary={false};runOnMainSync(()->{try{Method m=chat.getClass().getDeclaredMethod("bubble",entry.getClass(),int.class);m.setAccessible(true);View bubble=(View)m.invoke(chat,entry,0);ordinary[0]=!hasRepeatControl(bubble);}catch(Exception e){throw new RuntimeException(e);}});check(ordinary[0],"Compact message is an ordinary bubble without a repeat badge or expansion control");
  ListView results=(ListView)field(chat,"resultsList");final boolean[] clean={true};runOnMainSync(()->{for(int i=0;i<results.getAdapter().getCount();i++)if(hasRepeatControl(results.getAdapter().getView(i,null,results)))clean[0]=false;});check(clean[0],"Search results have no grouped badge or copy count");
  invoke(chat,"closeSearch");compact(chat,false);check(visible(chat,"Repeated example")==2,"Standard view restores both loaded source copies");c.getSharedPreferences("chat_reader",0).edit().putBoolean("search_groups:compact",false).commit();runOnMainSync(chat::finish);
  Activity reopened=startActivitySync(new Intent(c,ChatActivity.class).putExtra("chat","compact").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));idle(reopened);compact(reopened,true);check(visible(reopened,"Repeated example")==2,"Compact view hides extra copies while keeping the other sender distinct");search(reopened,"Repeated");check((Long)field(reopened,"totalMatches")==2,"Compact search overrides an old show-every-entry preference");check(((View)field(reopened,"groupSearchButton")).getVisibility()==View.GONE,"Compact search cannot expose copies through a grouping control");check(!((TextView)field(reopened,"matchCount")).getText().toString().contains("entries"),"Match counter shows unique results without raw-copy counts");select(reopened,"OwnerExample");check(visible(reopened,"Repeated example")==1,"Selecting a result keeps only one visible bubble");invoke(reopened,"closeSearch");check(visible(reopened,"Repeated example")==1,"Closing search keeps extra copies hidden");
  try(Cursor cur=db.rawQuery("SELECT COUNT(*),SUM(own) FROM messages WHERE chat='compact'",null)){cur.moveToFirst();check(cur.getInt(0)==3&&cur.getInt(1)==1,"No source messages or sender flags were removed or reassigned");}runOnMainSync(reopened::finish);
  Activity boundary=startActivitySync(new Intent(c,ChatActivity.class).putExtra("chat","boundary").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));idle(boundary);search(boundary,"Boundary");select(boundary,"OwnerExample");older(boundary);idle(boundary);check(visible(boundary,"Boundary marker")==1,"Matching copy across a raw page boundary stays folded during highlighted search");check(((List<?>)field(boundary,"entries")).size()==100,"Page-boundary folding keeps all 99 unrelated messages");invoke(boundary,"closeSearch");check(visible(boundary,"Boundary marker")==1,"Page-boundary group stays compact after closing search");runOnMainSync(boundary::finish);repo.close();
 }
}
